  static void Log(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){failed=true;report+="ERROR "+message+"\n"+stack+"\n";}}
  static void Check(bool ok,string title){if(!ok)throw new Exception(title);report+="PASS "+title+"\n";}
  static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;
   if(!running){if(!File.Exists("Logs/RunCafeFocused.flag"))return;if(EditorApplication.isPlaying){EditorApplication.isPlaying=false;return;}if(EditorApplication.isPlayingOrWillChangePlaymode)return;g=UnityEngine.Object.FindAnyObjectByType<CafeGame>();if(!g)return;File.Delete("Logs/RunCafeFocused.flag");g.testing=true;g.suppressSaveOnExit=true;Economy.Save(new SaveData(),g.SavePath);running=true;failed=false;report="COFFEE TYCOON CAFE FOCUS\n";began=EditorApplication.timeSinceStartup;SessionState.SetBool("FocusedCheck",true);SessionState.SetInt("CafePreviousPlayOptions",(int)EditorSettings.enterPlayModeOptions);EditorSettings.enterPlayModeOptions=EnterPlayModeOptions.DisableDomainReload;Application.logMessageReceived+=Log;EditorApplication.isPlaying=true;return;}
   if(!EditorApplication.isPlaying)return;
   try{if(EditorApplication.timeSinceStartup-began>180)throw new Exception("Timeout");g=UnityEngine.Object.FindAnyObjectByType<CafeGame>();if(!g||!g.ui||!g.GetComponent<CafeFocusedMode>())return;if(g.GetComponent<CafeFocusedProbe>())return;Validate();g.gameObject.AddComponent<CafeFocusedProbe>().Begin(g);var view=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("UnityEditor.GameView")).FirstOrDefault(t=>t!=null);if(view!=null)EditorWindow.GetWindow(view).Focus();}catch(Exception e){Finish("FAIL "+e);}}
