   g.Spawn();var first=g.customers.Last();first.state=CafeCustomer.State.Waiting;first.recipe=0;m.SelectOrder(first);m.ClickPrimary();int beans=g.data.beans;m.PressDown();m.TickHold(.2f);m.PressUp();m.ClickPrimary();Check(g.data.beans==beans&&!g.cup.ground,"Interrupted hold consumes no stock");g.Discard();g.customers.Remove(first);UnityEngine.Object.Destroy(first.gameObject);
   foreach(int recipe in Enumerable.Range(0,10)){g.Spawn();var c=g.customers.Last();c.state=CafeCustomer.State.Waiting;c.recipe=recipe;c.transform.position=c.QueuePosition;m.SelectOrder(c);m.ClickPrimary();for(int i=0;i<20&&g.cup!=null;i++){string key=m.ActionKey;if(key=="pickup"){Check(g.IsGood(g.cup),"Correct recipe "+Economy.Recipes[recipe].name);m.ClickPrimary();break;}if(CafeFocusedMode.HoldAction(key)){m.PressDown();m.TickHold(2);m.PressUp();m.ClickPrimary();}else if(key=="machine"){m.ClickPrimary();if(g.brewTime>0){g.brewTime=g.brewTotal*.15f;m.ClickPrimary();}if(g.CupOnMachine)m.ClickPrimary();}else m.ClickPrimary();}Check(g.cup==null&&c.state==CafeCustomer.State.ToPickup,"Counter serves recipe "+recipe);int money=g.data.money;for(int i=0;i<12000&&c.state!=CafeCustomer.State.Drinking;i++)c.SendMessage("Update");Check(c.state==CafeCustomer.State.Drinking&&g.data.money>money,"Customer collects and pays "+recipe);}
