   var h=g.GetComponent<CafeHundred>();g.cup=new CupWork();h.Ground(g.cup);g.data.machine=1;h.StartBrew();float slow=g.brewTotal;g.data.machine=5;h.StartBrew();Check(g.brewTotal<slow,"Machine upgrade shortens preparation");g.brewTime=0;g.cup=null;g.Save();var save=Economy.Load(g.SavePath);Check(save.served==g.data.served&&save.hundred.mastery.SequenceEqual(h.Data.mastery),"Isolated save round trip preserves service progression");CafeArtDirectionChecks.Validate(g);report+=CafeArtDirectionChecks.Report;CafeStreetSurfaceChecks.Validate(g);report+=CafeStreetSurfaceChecks.Report;CafeDecorChecks.Validate(g);report+=CafeDecorChecks.Report;CafeInteriorChecks.Validate(g);report+=CafeInteriorChecks.Report;CafeRearBarChecks.Validate(g);report+=CafeRearBarChecks.Report;CafeCustomerVisualChecks.Validate(g);report+=CafeCustomerVisualChecks.Report;CafeTouchChecks.Validate(g);report+=CafeTouchChecks.Report;CafeCoffeeSafetyChecks.Validate(g);report+=CafeCoffeeSafetyChecks.Report;CafeLatteSafetyChecks.Validate(g);report+=CafeLatteSafetyChecks.Report;CafeOrderGuideChecks.Validate(g);report+=CafeOrderGuideChecks.Report;CafeSupplyChecks.Validate(g);report+=CafeSupplyChecks.Report;CafePointerChecks.Validate(g);report+=CafePointerChecks.Report;CafeModalChecks.Validate(g);report+=CafeModalChecks.Report;CafeDeliveryChecks.Validate(g);report+=CafeDeliveryChecks.Report;CafeTrayManagerChecks.Validate(g);report+=CafeTrayManagerChecks.Report;CafeTypographyChecks.Validate(g);report+=CafeTypographyChecks.Report;CafeNaturalDetailChecks.Validate(g);report+=CafeNaturalDetailChecks.Report;CafeBoulevardChecks.Validate(g);report+=CafeBoulevardChecks.Report;CafePropAudit.Validate(g);report+=CafePropAudit.Report;g.data.dayTime=120;g.Tell("Kafe içi servis testi tamamlandı.",true);}
  public static bool CheckRenderedPointer(CafeGame game){try{CafeOrderTextChecks.Validate(game);report+="PASS All ten recipe names and 64 preference/step pairs fit order cards without clipping\n";var prints=game.GetComponentsInChildren<CafePrintedLabel>();if(prints.Length<4)throw new Exception("Packaging print labels missing");foreach(var print in prints){var mesh=print.GetComponent<TextMesh>();var bounds=print.GetComponent<Renderer>().localBounds.size;if(!print.fitted||mesh.font!=CafeTypography.Strong||bounds.x>print.area.x+.001f||bounds.y>print.area.y+.001f)throw new Exception("Packaging print exceeds physical label: "+mesh.text);}report+="PASS Packaging prints use bundled font and fit physical label bounds\n";string prior=CafePointerChecks.Report;CafePointerChecks.ValidateRaycasts(game);report+=CafePointerChecks.Report.Substring(prior.Length);return true;}catch(Exception e){Finish("FAIL "+e);return false;}}
    public static bool VisualCheck(bool ok,string title){if(!ok){Finish("FAIL "+title);return false;}report+="PASS "+title+"\n";return true;}
  public static bool BasketPhysics(CafeGame game,int before){try{if(game.data.money!=before+50)throw new Exception("Physical ball did not score exactly 50");report+="PASS Live Rigidbody falls through hollow rim and pays exactly 50 coins\n";return true;}catch(Exception e){Finish("FAIL "+e);return false;}}
  public static void Measured(List<float> frames,long memory){frames.Sort();if(failed||frames.Count<120||memory>=2147483648L){Finish("FAIL rendered gameplay or runtime log error");return;}Check(true,"Stable rendered gameplay");report+="PERFORMANCE "+(1/frames[frames.Count/2]).ToString("0.0")+" FPS, "+memory/1048576+" MB\n";Finish("ALL CAFE FOCUS CHECKS PASSED");}
  static void Finish(string status){CafeAspectChecks.Restore();report+=CafeAspectChecks.Report;CafeAspectChecks.Report="";File.WriteAllText("Logs/CafeFocusedCheck.txt",report+status+"\n");EditorApplication.isPlaying=false;}
